// =============================================================================
// Lookup Functions
// =============================================================================

/// Get feature entries for a tile type by name.
pub fn getFeaturesForTileType(tile_type_name: []const u8) ?[]const FeatureEntry {
    if (std.mem.eql(u8, tile_type_name, "BRAM_L")) return &bram_l_features;
    if (std.mem.eql(u8, tile_type_name, "BRAM_R")) return &bram_r_features;
    if (std.mem.eql(u8, tile_type_name, "CLBLL_L")) return &clbll_l_features;
    if (std.mem.eql(u8, tile_type_name, "CLBLL_R")) return &clbll_r_features;
    if (std.mem.eql(u8, tile_type_name, "CLBLM_L")) return &clblm_l_features;
    if (std.mem.eql(u8, tile_type_name, "CLBLM_R")) return &clblm_r_features;
    if (std.mem.eql(u8, tile_type_name, "CLK_BUFG_BOT_R")) return &clk_bufg_bot_r_features;
    if (std.mem.eql(u8, tile_type_name, "CLK_BUFG_REBUF")) return &clk_bufg_rebuf_features;
    if (std.mem.eql(u8, tile_type_name, "CLK_BUFG_TOP_R")) return &clk_bufg_top_r_features;
    if (std.mem.eql(u8, tile_type_name, "CLK_HROW_BOT_R")) return &clk_hrow_bot_r_features;
    if (std.mem.eql(u8, tile_type_name, "CLK_HROW_TOP_R")) return &clk_hrow_top_r_features;
    if (std.mem.eql(u8, tile_type_name, "DSP_L")) return &dsp_l_features;
    if (std.mem.eql(u8, tile_type_name, "DSP_R")) return &dsp_r_features;
    if (std.mem.eql(u8, tile_type_name, "HCLK_CMT")) return &hclk_cmt_features;
    if (std.mem.eql(u8, tile_type_name, "HCLK_CMT_L")) return &hclk_cmt_l_features;
    if (std.mem.eql(u8, tile_type_name, "HCLK_L")) return &hclk_l_features;
    if (std.mem.eql(u8, tile_type_name, "HCLK_R")) return &hclk_r_features;
    if (std.mem.eql(u8, tile_type_name, "INT_L")) return &int_l_features;
    if (std.mem.eql(u8, tile_type_name, "INT_R")) return &int_r_features;
    if (std.mem.eql(u8, tile_type_name, "LIOB33")) return &liob33_features;
    if (std.mem.eql(u8, tile_type_name, "LIOI3")) return &lioi3_features;
    if (std.mem.eql(u8, tile_type_name, "RIOB33")) return &riob33_features;
    if (std.mem.eql(u8, tile_type_name, "RIOI3")) return &rioi3_features;
    return null;
}

/// Binary search for a feature within a tile type's feature table.
pub fn findFeature(features: []const FeatureEntry, name: []const u8) ?*const FeatureEntry {
    var lo: usize = 0;
    var hi: usize = features.len;
    while (lo < hi) {
        const mid = lo + (hi - lo) / 2;
        const cmp = std.mem.order(u8, features[mid].feature, name);
        switch (cmp) {
            .eq => return &features[mid],
            .lt => lo = mid + 1,
            .gt => hi = mid,
        }
    }
    return null;
}

// =============================================================================
// Statistics
// =============================================================================

pub const total_features: u32 = 20904;
pub const total_bits: u32 = 51174;
pub const tile_type_count: u32 = 23;

// =============================================================================
// Tests
// =============================================================================

test "segbits data loaded" {
    try std.testing.expect(total_features > 0);
    try std.testing.expect(total_bits > 0);
    try std.testing.expect(tile_type_count > 0);
}

test "feature lookup" {
    const features = &bram_l_features;
    const found = findFeature(features, "BRAM_L.BRAM_ADDRARDADDRL0.BRAM_CASCINBOT_ADDRARDADDRU0");
    try std.testing.expect(found != null);
}

test "tile type lookup" {
    const features = getFeaturesForTileType("BRAM_L");
    try std.testing.expect(features != null);
    try std.testing.expect(features.?.len > 0);
}

